            "code": "package main\n\nimport (\n\t\"bytes\"\n\t\"io\"\n\t\"mime/multipart\"\n\t\"net/http\"\n\t\"net/textproto\"\n\t\"os\"\n\t\"path/filepath\"\n\t\"strings\"\n)\n\nfunc main() {\n\turl := os.Getenv(\"BLAZING_AGENTS_BASE_URL\") + \"/v1/agents/ag_1234567890ABCDEF/avatar\"\n\tvar body io.Reader = http.NoBody\n\tbuffer := new(bytes.Buffer)\n\twriter := multipart.NewWriter(buffer)\n\tpartHeader := make(textproto.MIMEHeader)\n\tpartHeader.Set(\"Content-Disposition\", \"form-data; name=\\\"file\\\"; filename=\\\"\" + filepath.Base(\"./avatar.webp\") + \"\\\"\")\n\tpartHeader.Set(\"Content-Type\", \"image/webp\")\n\tpart, err := writer.CreatePart(partHeader)\n\tif err != nil { panic(err) }\n\tfile, err := os.Open(\"./avatar.webp\")\n\tif err != nil { panic(err) }\n\t_, _ = io.Copy(part, file)\n\t_ = file.Close()\n\t_ = writer.Close()\n\tbody = strings.NewReader(buffer.String())\n\trequest, err := http.NewRequest(\"POST\", url, body)\n\tif err != nil { panic(err) }\n\trequest.Header.Set(\"Authorization\", \"Bearer \" + os.Getenv(\"BLAZING_AGENTS_API_KEY\"))\n\trequest.Header.Set(\"Content-Type\", writer.FormDataContentType())\n\tresponse, err := http.DefaultClient.Do(request)\n\tif err != nil { panic(err) }\n\tdefer response.Body.Close()\n\t_, _ = io.Copy(os.Stdout, response.Body)\n}",
